#include "ui_drawing.hpp"
#ifdef OLED_128x32

uint8_t buttonAF[sizeof(buttonA)];
uint8_t buttonBF[sizeof(buttonB)];
uint8_t disconnectedTipF[sizeof(disconnectedTip)];

void ui_pre_render_assets(void) {
  // Generate the flipped screen into ram for later use
  // flipped is generated by flipping each row
  for (int row = 0; row < 4; row++) {
    for (int x = 0; x < 56; x++) {
      // Only the first 42 columns hold the pictogram; past that 41 - x would read the previous row
      buttonAF[(row * 56) + x]         = x < 42 ? buttonA[(row * 56) + (41 - x)] : 0;
      buttonBF[(row * 56) + x]         = x < 42 ? buttonB[(row * 56) + (41 - x)] : 0;
      disconnectedTipF[(row * 56) + x] = x < 42 ? disconnectedTip[(row * 56) + (41 - x)] : 0;
    }
  }
}
#endif